// Local prototype, not wired into a live DSH session.
import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';
const digest=s=>crypto.createHash('sha256').update(s).digest('hex');
const valid=s=>typeof s==='string'&&s.length>0&&s.length<=200;
const validProvenance=p=>p&&typeof p==='object'&&!Array.isArray(p)&&Number.isSafeInteger(p.cid)&&p.cid>0&&((Object.keys(p).sort().join(',')==='cid,end,kind,model,start'&&p.kind==='local_asr'&&Number.isFinite(p.start)&&Number.isFinite(p.end)&&p.start>=0&&p.end>p.start&&p.end-p.start<=62&&p.model==='faster-whisper-base-cpu-int8')||(Object.keys(p).sort().join(',')==='cid,frameCount,frameOffset,kind,nextOffset'&&p.kind==='sampled_frames'&&Number.isSafeInteger(p.frameCount)&&p.frameCount>0&&p.frameCount<=1200&&Number.isSafeInteger(p.frameOffset)&&p.frameOffset>=0&&p.frameOffset<p.frameCount&&(p.nextOffset===null||(Number.isSafeInteger(p.nextOffset)&&p.nextOffset>p.frameOffset&&p.nextOffset<p.frameCount))));
export class BrowsingArchive {
 constructor(root,{account,session}){if(!valid(account)||!valid(session)||typeof root!=='string'||!path.isAbsolute(root))throw Error('INVALID_SCOPE');this.root=path.resolve(root);this.file=path.join(this.root,digest(account+'\0'+session)+'.json');}
 verifyRoot(){let current=this.root;for(;;){try{const st=fs.lstatSync(current);if(st.isSymbolicLink()||!st.isDirectory())throw Error('UNSAFE_ARCHIVE_PATH');}catch(e){if(e.code!=='ENOENT')throw e;}const parent=path.dirname(current);if(parent===current)break;current=parent;}}
 ensureRoot(){this.verifyRoot();fs.mkdirSync(this.root,{recursive:true});this.verifyRoot();}
 read(){this.verifyRoot();let st;try{st=fs.lstatSync(this.file);}catch(e){if(e.code==='ENOENT')return {version:1,entries:[],deleted:[]};throw e;}if(!st.isFile()||st.isSymbolicLink()||st.size>8*1024*1024)throw Error('INVALID_ARCHIVE');const data=JSON.parse(fs.readFileSync(this.file,'utf8'));if(data.version!==1||!Array.isArray(data.entries)||!Array.isArray(data.deleted)||data.entries.length>5000||data.deleted.length>5000)throw Error('INVALID_ARCHIVE');return data;}
 write(data){this.ensureRoot();const temp=path.join(this.root,'.archive-'+crypto.randomUUID()+'.tmp');try{fs.writeFileSync(temp,JSON.stringify(data),{flag:'wx',mode:0o600});this.verifyRoot();fs.renameSync(temp,this.file);}finally{if(fs.existsSync(temp))fs.unlinkSync(temp);}}
 withLock(fn){this.ensureRoot();const lock=this.file+'.lock',token=crypto.randomUUID();let fd;try{fd=fs.openSync(lock,'wx',0o600);}catch(e){if(e.code==='EEXIST')throw Error('ARCHIVE_BUSY');throw e;}try{fs.writeFileSync(fd,token);fs.closeSync(fd);fd=undefined;return fn();}finally{if(fd!==undefined)fs.closeSync(fd);try{const st=fs.lstatSync(lock);if(st.isFile()&&!st.isSymbolicLink()&&fs.readFileSync(lock,'utf8')===token)fs.unlinkSync(lock);}catch(e){if(e.code!=='ENOENT')throw e;}}}
 add(entry){if(!entry||!/^[A-Za-z0-9-]{1,80}$/.test(entry.id??'')||!/^BV[A-Za-z0-9]{10}$/.test(entry.bvid??'')||typeof entry.at!=='string'||!Number.isFinite(Date.parse(entry.at))||typeof entry.feeling!=='string'||entry.feeling.length>1000||typeof entry.title!=='string'||entry.title.length>200||!Number.isSafeInteger(entry.readPages)||!Number.isSafeInteger(entry.totalPages)||entry.totalPages<1||entry.readPages<1||entry.readPages>entry.totalPages||(entry.readPageIndex!==undefined&&(!Number.isSafeInteger(entry.readPageIndex)||entry.readPageIndex<0||entry.readPageIndex>=entry.totalPages))||(entry.provenance!==undefined&&!validProvenance(entry.provenance))||!['unshared','shared'].includes(entry.shareState))throw Error('INVALID_ENTRY');return this.withLock(()=>{const data=this.read();if(data.deleted.includes(entry.id))return {status:'deleted'};const previous=data.entries.find(x=>x.id===entry.id);const p=entry.provenance;const provenance=p?.kind==='sampled_frames'?{kind:p.kind,cid:p.cid,frameCount:p.frameCount,frameOffset:p.frameOffset,nextOffset:p.nextOffset}:p?{kind:p.kind,cid:p.cid,start:p.start,end:p.end,model:p.model}:undefined;const item={id:entry.id,bvid:entry.bvid,title:entry.title,at:entry.at,feeling:entry.feeling,readPages:entry.readPages,totalPages:entry.totalPages,shareState:entry.shareState,...(entry.readPageIndex!==undefined?{readPageIndex:entry.readPageIndex}:{}),...(provenance?{provenance}:{})};if(previous){if(JSON.stringify(previous)!==JSON.stringify(item))throw Error('ENTRY_CONFLICT');return {status:'exists'};}if(data.entries.length>=5000)throw Error('ARCHIVE_FULL');data.entries.push(item);this.write(data);return {status:'saved'};});}
 list(){return this.read().entries;}
 remove(id){if(!/^[A-Za-z0-9-]{1,80}$/.test(id??''))throw Error('INVALID_ID');return this.withLock(()=>{const data=this.read();const index=data.entries.findIndex(x=>x.id===id);if(index<0)return false;if(data.deleted.length>=5000)throw Error('ARCHIVE_FULL');data.entries.splice(index,1);if(!data.deleted.includes(id))data.deleted.push(id);this.write(data);return true;});}
}
